#include <iostream>
using namespace std;

void scambioErrato(int a, int b);
void scambioCorretto(int &a, int &b);

int main() {
    int x = 5, y = 10;
    scambioErrato(x, y);
    cout << "Dopo il passaggio per valore: "
         << x << " " << y << endl;
    scambioCorretto(x, y);
    cout << "Dopo il passaggio per riferimento: "
         << x << " " << y << endl;
    return 0;
}

void scambioErrato(int a, int b) {
    int temp = a;
    a = b;
    b = temp;
}

void scambioCorretto(int &a, int &b) {
    int temp = a;
    a = b;
    b = temp;
}

#include <iostream>
using namespace std;

int sommaArray(const int arr[], int dimensione) {
    int somma = 0;
    for (int i = 0; i < dimensione; i++) {
        somma += arr[i];
    }
    return somma;
}

void raddoppiaElementi(int arr[], int dimensione) {
    for (int i = 0; i < dimensione; i++) {
        arr[i] *= 2;
    }
}

int main() {
    int numeri[] = {1, 2, 3, 4, 5};
    int dimensione = sizeof(numeri) / sizeof(numeri[0]);
    cout << "Somma: " << sommaArray(numeri, dimensione) << endl;
    raddoppiaElementi(numeri, dimensione);
    for (int i = 0; i < dimensione; i++) {
        cout << numeri[i] << " ";
    }
    return 0;
}

