#include <iostream>
using namespace std;

int fattoriale(int n) {
    if (n <= 1) {
        return 1;
    }
    int risultato = n * fattoriale(n - 1);
    return risultato;
}

int main() {
    int numero = 4;
    int risultato = fattoriale(numero);
    cout << "Fattoriale: " << risultato << endl;
    return 0;
}

#include <iostream>
using namespace std;

void incrementa(int *p) {
    *p = *p + 1;
}

int main() {
    int numero = 10;
    int voti[3] = {6, 7, 8};
    int *p = &numero;
    incrementa(p);
    p = &voti[1];
    incrementa(p);
    cout << "Numero: " << numero << endl;
    cout << "Secondo voto: " << voti[1] << endl;
    return 0;
}
